  CALL SGET_HOST_DATA_RDONLY (PAPH, YD_PAPH)
  CALL SGET_HOST_DATA_RDWR (PMFD, YD_PMFD)
  CALL SGET_HOST_DATA_RDONLY (PTENU, YD_PTENU)
  CALL SGET_HOST_DATA_RDONLY (PTENV, YD_PTENV)
  CALL SGET_HOST_DATA_RDWR (ZDMFDP, YL_ZDMFDP)
