      ENDDO


      DO JK=1, KLEV
        
        PMFD (JLON, JK, JBLK)=0.0_JPRB
        ZMFDS (JLON, JK, JBLK)=0.0_JPRB
        ZMFDQ (JLON, JK, JBLK)=0.0_JPRB
        ZDMFDP (JLON, JK, JBLK)=0.0_JPRB
        ZDPMEL (JLON, JK, JBLK)=0.0_JPRB
      
      ENDDO


      DO JK=1, KLEV
        
        ZTENU (JLON, JK, JBLK)=PTENU (JLON, JK, JBLK)
