ELSEIF (FXTRAN_ACDC_LPARALLELMETHOD ('OPENACCSINGLECOLUMN','CUMASTRN_PARALLEL:5')) THEN
  
  IF (LHOOK) CALL DR_HOOK ('CUMASTRN_PARALLEL:5:GET_DATA',0,ZHOOK_HANDLE_FIELD_API)
