    & JBLK), ZDMFUP(:,:, JBLK), ZDMFDP(:,:, JBLK), ZDPMEL(:,:, JBLK), PLGLAC(:,:, JBLK), PMFLXR(:,:, JBLK&
    &), PMFLXS(:,:, JBLK), PRAIN(:, JBLK), PMFUDE_RATE(:,:, JBLK), PMFDDE_RATE(:,:, JBLK))
