    ZMFDDR => NULL ()
    ZMFDUS => NULL ()
    ZMFS => NULL ()
    ZMFUDR => NULL ()
    ZMFUUS => NULL ()
    IF (LHOOK) CALL DR_HOOK ('CUMASTRN_PARALLEL:16:NULLIFY',1,ZHOOK_HANDLE_FIELD_API)
    
    
  ELSE
      CALL ABOR1 ('CUMASTRN_PARALLEL: NOT METHOD WAS FOUND')
  ENDIF

  IF (LHOOK) CALL DR_HOOK ('CUMASTRN_PARALLEL:16',1,ZHOOK_HANDLE_PARALLEL)
ENDIF

