ELSEIF (FXTRAN_ACDC_LPARALLELMETHOD ('OPENACCSINGLECOLUMN','CUMASTRN_PARALLEL:17')) THEN
  
  IF (LHOOK) CALL DR_HOOK ('CUMASTRN_PARALLEL:17:GET_DATA',0,ZHOOK_HANDLE_FIELD_API)
  CALL SGET_DEVICE_DATA_RDONLY (KCTOP, YD_KCTOP)
  CALL SGET_DEVICE_DATA_RDONLY (LDCUM, YD_LDCUM)
  CALL SGET_DEVICE_DATA_RDONLY (PAP, YD_PAP)
  CALL SGET_DEVICE_DATA_RDWR (PDISS, YD_PDISS)
  CALL SGET_DEVICE_DATA_RDWR (PENTH, YD_PENTH)
  CALL SGET_DEVICE_DATA_RDONLY (PGEOH, YD_PGEOH)
  CALL SGET_DEVICE_DATA_RDWR (PLU, YD_PLU)
  CALL SGET_DEVICE_DATA_RDWR (PLUDE, YD_PLUDE)
  CALL SGET_DEVICE_DATA_RDWR (PLUDELI, YD_PLUDELI)
  CALL SGET_DEVICE_DATA_RDWR (PMFD, YD_PMFD)
  CALL SGET_DEVICE_DATA_RDWR (PMFDDE_RATE, YD_PMFDDE_RATE)
  CALL SGET_DEVICE_DATA_RDONLY (PMFLXR, YD_PMFLXR)
  CALL SGET_DEVICE_DATA_RDONLY (PMFLXS, YD_PMFLXS)
  CALL SGET_DEVICE_DATA_RDWR (PMFU, YD_PMFU)
  CALL SGET_DEVICE_DATA_RDWR (PMFUDE_RATE, YD_PMFUDE_RATE)
  CALL SGET_DEVICE_DATA_RDONLY (PQEN, YD_PQEN)
